from pysat.card import CardEnc, EncType
from pysat.formula import CNF
from pysat.solvers import Glucose3
from itertools import combinations, permutations

n=12
var_map = {}
vid = 1
for u,v in combinations(range(n),2):
    var_map[(u,v)] = vid
    vid+=1

def E(u,v):
    if u>v: u,v=v,u
    return var_map[(u,v)]

cnf = CNF()

for a,b,c in combinations(range(n),3):
    cnf.append([-E(a,b), -E(a,c), -E(b,c)])

for quad in combinations(range(n),4):
    a,b,c,d = quad
    for perm in [(a,b,c,d),(a,b,d,c),(a,c,b,d)]:
        p,q,r,s = perm
        cnf.append([-E(p,q),-E(q,r),-E(r,s),-E(s,p)])

for quint in combinations(range(n),5):
    a = quint[0]
    rest = quint[1:]
    seen=set()
    for perm in permutations(rest):
        cyc = (a,)+perm
        key = min(cyc[i:]+cyc[:i] for i in range(5))
        rev = tuple(reversed(key))
        keyr = min(rev[i:]+rev[:i] for i in range(5))
        canon = min(key,keyr)
        if canon in seen: continue
        seen.add(canon)
        cl=[]
        for i in range(5):
            cl.append(-E(cyc[i], cyc[(i+1)%5]))
        cnf.append(cl)

top = vid
for v in range(n):
    lits = [E(v,u) for u in range(n) if u!=v]
    c1 = CardEnc.atleast(lits=lits, bound=3, top_id=top, encoding=EncType.seqcounter)
    for cl in c1.clauses: 
        cnf.append(cl)
        for l in cl:
            if abs(l)>top: top=abs(l)
    c2 = CardEnc.atmost(lits=lits, bound=6, top_id=top, encoding=EncType.seqcounter)
    for cl in c2.clauses: 
        cnf.append(cl)
        for l in cl:
            if abs(l)>top: top=abs(l)

print("clauses:", len(cnf.clauses), "vars:", top)

solver = Glucose3()
for cl in cnf.clauses:
    solver.add_clause(cl)

import time
t=time.time()
result = solver.solve()
print("solved in", time.time()-t, "result:", result)

if result:
    model = solver.get_model()
    edges = []
    for (u,v), vv in var_map.items():
        if model[vv-1] > 0:
            edges.append((u,v))
