                    for v in adj[u]:
                        if dist[v]==-1:
                            dist[v]=dist[u]+1; parent[v]=u; nq.append(v)
                        elif parent[u]!=v:
                            c=dist[u]+dist[v]+1
                            if c<g: g=c
                q=nq
        return g
    print("girth:", girth(adj))
